import java.util.*; class SummaryRanges { private TreeMap<Integer, Integer> map; public SummaryRanges() { map = new TreeMap<>(); } public void addNum(int value) { Integer low = map.floorKey(value); Integer high = map.ceilingKey(value); if (low != null && map.get(low) >= value) return; boolean canMergeLow = (low != null && map.get(low) == value - 1); boolean canMergeHigh = (high != null && high == value + 1); if (canMergeLow && canMergeHigh) { map.put(low, map.get(high)); map.remove(high); } else if (canMergeLow) { map.put(low, value); } else if (canMergeHigh) { map.put(value, map.get(high)); map.remove(high); } else { map.put(value, value); } } public int[][] getIntervals() { int[][] res = new int[map.size()][2]; int i = 0; for (Map.Entry<Integer, Integer> entry : map.entrySet()) { res[i][0] = entry.getKey(); res[i][1] = entry.getValue(); i++; } return res; } }